// TypeScript Model: Synthetic Securitization vs True Sale Capital Architecture
interface SyntheticPortfolio {
  portfolioNotional: number;      // e.g., 8,000,000,000
  baselineRiskWeight: number;     // e.g., 1.00 (100%)
  targetCET1Ratio: number;        // e.g., 0.12 (12%)
  clnTrancheNotional: number;     // e.g., 560,000,000 (7%)
  clnCouponSpreadBps: number;     // e.g., 950 bps (9.50%)
  seniorRetainedRiskWeight: number; // e.g., 0.15 (15%)
}

function evaluateSyntheticRelief(p: SyntheticPortfolio) {
  const baselineRWA = p.portfolioNotional * p.baselineRiskWeight;
  const baselineCapitalRequired = baselineRWA * p.targetCET1Ratio;

  // Post-SRT retained senior tranche + any retained junior slice
  const retainedSeniorNotional = p.portfolioNotional - p.clnTrancheNotional;
  const postSrtRWA = retainedSeniorNotional * p.seniorRetainedRiskWeight;
  const postSrtCapitalRequired = postSrtRWA * p.targetCET1Ratio;

  const capitalFreed = baselineCapitalRequired - postSrtCapitalRequired;
  const annualProtectionCost = p.clnTrancheNotional * (p.clnCouponSpreadBps / 10000);

  // Return on Capital Freed (Cost of Capital vs Return on Equity)
  const costOfFreedCapital = annualProtectionCost / capitalFreed;

  return {
    baselineRWA,
    postSrtRWA,
    rwaReductionPercent: ((baselineRWA - postSrtRWA) / baselineRWA) * 100,
    capitalFreed,
    annualProtectionCost,
    costOfFreedCapitalPercent: costOfFreedCapital * 100
  };
}

// TypeScript Model: Significant Risk Transfer (SRT) Regulatory Qualification Engine
interface SrtQualificationInput {
  portfolioNotional: number;         // e.g., 5,000,000,000
  portfolioExpectedLossRate: number; // e.g., 0.012 (1.2%)
  firstLossAttachment: number;       // e.g., 0.00 (0%)
  firstLossDetachment: number;       // e.g., 0.02 (2%)
  firstLossTransferredPct: number;   // e.g., 1.00 (100%)
  mezzanineAttachment: number;       // e.g., 0.02 (2%)
  mezzanineDetachment: number;       // e.g., 0.08 (8%)
  mezzanineTransferredPct: number;   // e.g., 1.00 (100%)
  hasCreditDeteriorationStepUp: boolean;
  hasUncappedCleanUpCall: boolean;
}

interface SrtQualificationResult {
  portfolioExpectedLossNotional: number;
  firstLossNotional: number;
  mezzanineNotional: number;
  firstLossMultipleOfEL: number;
  mezzanineTransferPass: boolean;
  firstLossTransferPass: boolean;
  qualitativePass: boolean;
  overallSrtApproved: boolean;
  rejectionReasons: string[];
}

function evaluateRegulatorySRT(input: SrtQualificationInput): SrtQualificationResult {
  const elNotional = input.portfolioNotional * input.portfolioExpectedLossRate;
  const flNotional = input.portfolioNotional * (input.firstLossDetachment - input.firstLossAttachment);
  const mezzNotional = input.portfolioNotional * (input.mezzanineDetachment - input.mezzanineAttachment);

  const flMultiple = flNotional / elNotional;
  const rejectionReasons: string[] = [];

  // Quantitative Test 1: Mezzanine transfer >= 50%
  const mezzPass = input.mezzanineTransferredPct >= 0.50;
  if (!mezzPass) rejectionReasons.push('Mezzanine transferred percentage is below statutory 50% threshold.');

  // Quantitative Test 2: First-loss >= 1.0x EL and transferred >= 80%
  const flPass = flMultiple >= 1.0 && input.firstLossTransferredPct >= 0.80;
  if (!flPass) rejectionReasons.push('First-loss tranche sizing is insufficient relative to EL or transfer pct < 80%.');

  // Qualitative Tests: No step-ups, clean-up call <= 10%
  let qualPass = true;
  if (input.hasCreditDeteriorationStepUp) {
    qualPass = false;
    rejectionReasons.push('Contract contains prohibited credit-deterioration coupon step-up.');
  }
  if (input.hasUncappedCleanUpCall) {
    qualPass = false;
    rejectionReasons.push('Contract contains non-compliant clean-up call violating supervisory guidelines.');
  }

  const overallApproved = (mezzPass || flPass) && qualPass;

  return {
    portfolioExpectedLossNotional: elNotional,
    firstLossNotional: flNotional,
    mezzanineNotional: mezzNotional,
    firstLossMultipleOfEL: flMultiple,
    mezzanineTransferPass: mezzPass,
    firstLossTransferPass: flPass,
    qualitativePass: qualPass,
    overallSrtApproved: overallApproved,
    rejectionReasons
  };
}

// TypeScript Model: Tranche Thickness Determination & Loss Absorption Calibration
interface TrancheSizingParameters {
  portfolioNotional: number;
  cumulativeExpectedLossRate: number;  // e.g., 0.011 (1.10%)
  regulatoryK_IRB: number;             // e.g., 0.052 (5.20%)
  stressLossP99_9: number;             // e.g., 0.085 (8.50% at 99.9% VaR)
  investorTargetYieldSpread: number;   // e.g., 0.095 (9.50% blended)
}

interface TrancheArchitecture {
  firstLossAttachment: number;
  firstLossDetachment: number;
  firstLossNotional: number;
  mezzanineAttachment: number;
  mezzanineDetachment: number;
  mezzanineNotional: number;
  seniorAttachment: number;
  seniorDetachment: number;
  seniorNotional: number;
  totalProtectionPurchasedNotional: number;
  protectionThicknessPercent: number;
  seniorTrancheQualifiesForFloorRiskWeight: boolean;
}

function calculateTrancheSizing(p: TrancheSizingParameters): TrancheArchitecture {
  // First-loss sized to cover 1.35x expected loss for safety buffer
  const flDetachment = Math.ceil(p.cumulativeExpectedLossRate * 1.35 * 1000) / 1000;
  const flNotional = p.portfolioNotional * flDetachment;

  // Mezzanine sized to detach comfortably above K_IRB and capture unexpected loss
  // Ensuring detachment point D2 >= K_IRB + buffer (e.g. at least 1.3x K_IRB)
  const mezzDetachment = Math.ceil(Math.max(p.regulatoryK_IRB * 1.30, 0.070) * 1000) / 1000;
  const mezzNotional = p.portfolioNotional * (mezzDetachment - flDetachment);

  const seniorAttachment = mezzDetachment;
  const seniorNotional = p.portfolioNotional * (1.0 - seniorAttachment);

  const totalProtection = flNotional + mezzNotional;
  const protectionThickness = mezzDetachment * 100;

  return {
    firstLossAttachment: 0.0,
    firstLossDetachment: flDetachment,
    firstLossNotional: flNotional,
    mezzanineAttachment: flDetachment,
    mezzanineDetachment: mezzDetachment,
    mezzanineNotional: mezzNotional,
    seniorAttachment: seniorAttachment,
    seniorDetachment: 1.0,
    seniorNotional: seniorNotional,
    totalProtectionPurchasedNotional: totalProtection,
    protectionThicknessPercent: protectionThickness,
    seniorTrancheQualifiesForFloorRiskWeight: seniorAttachment >= p.regulatoryK_IRB
  };
}

// TypeScript Model: SEC-IRBA Capital Relief & Return on Equity (ROE) Optimizer
interface SecuritizationCapitalInput {
  portfolioNotional: number;         // e.g., 10,000,000,000
  unsecuritizedRwaRate: number;      // e.g., 0.80 (80%)
  cet1TargetRatio: number;           // e.g., 0.12 (12%)
  bankCostOfEquity: number;          // e.g., 0.145 (14.5%)
  retainedSeniorRiskWeight: number;  // e.g., 0.15 (15% SEC-IRBA floor)
  protectionThicknessRate: number;   // e.g., 0.08 (8% = $800M)
  protectionCouponSpreadBps: number; // e.g., 1000 bps (10.0%)
}

interface SecuritizationEconomicsResult {
  baselineRWA: number;
  baselineCET1Capital: number;
  postSrtRWA: number;
  postSrtCET1Capital: number;
  rwaReliefNotional: number;
  capitalFreedNotional: number;
  annualProtectionFee: number;
  costOfFreedCapitalPercent: number;
  annualNetEconomicValueAdd: number;
  isAccretiveToShareholders: boolean;
}

function analyzeSrtEconomics(input: SecuritizationCapitalInput): SecuritizationEconomicsResult {
  const baselineRWA = input.portfolioNotional * input.unsecuritizedRwaRate;
  const baselineCapital = baselineRWA * input.cet1TargetRatio;

  const protectionNotional = input.portfolioNotional * input.protectionThicknessRate;
  const retainedSeniorNotional = input.portfolioNotional - protectionNotional;

  const postSrtRWA = retainedSeniorNotional * input.retainedSeniorRiskWeight;
  const postSrtCapital = postSrtRWA * input.cet1TargetRatio;

  const rwaRelief = baselineRWA - postSrtRWA;
  const capitalFreed = baselineCapital - postSrtCapital;

  const annualFee = protectionNotional * (input.protectionCouponSpreadBps / 10000);
  const costOfFreedCapital = (annualFee / capitalFreed) * 100;

  // Net Economic Value Add = Capital Freed * Bank Cost of Equity - Annual Protection Fee
  const grossCapitalBenefit = capitalFreed * input.bankCostOfEquity;
  const netValueAdd = grossCapitalBenefit - annualFee;

  return {
    baselineRWA,
    baselineCET1Capital: baselineCapital,
    postSrtRWA,
    postSrtCET1Capital: postSrtCapital,
    rwaReliefNotional: rwaRelief,
    capitalFreedNotional: capitalFreed,
    annualProtectionFee: annualFee,
    costOfFreedCapitalPercent: costOfFreedCapital,
    annualNetEconomicValueAdd: netValueAdd,
    isAccretiveToShareholders: netValueAdd > 0
  };
}

// Industrial TypeScript Simulation: Enterprise Synthetic SRT War Room Simulator
interface SrtWarRoomConfig {
  portfolioNotional: number;         // 12,000,000,000
  borrowerCount: number;             // 1,200
  annualizedPD: number;              // 0.014 (1.40%)
  weightedLGD: number;               // 0.40 (40%)
  weightedAverageLifeYears: number;  // 4.0
  unsecuritizedRiskWeight: number;   // 0.85 (85%)
  targetCET1Ratio: number;           // 0.12 (12%)
  bankCostOfEquity: number;          // 0.135 (13.5%)
  firstLossThicknessRate: number;    // 0.025 (2.5% = €300M)
  firstLossSpreadBps: number;        // 1350 bps
  mezzanineThicknessRate: number;    // 0.050 (5.0% = €600M)
  mezzanineSpreadBps: number;        // 850 bps
  seniorRetainedRiskWeight: number;  // 0.12 (12% SEC-IRBA floor)
}

interface StressScenario {
  name: string;
  cumulativeDefaultRate: number; // e.g., 0.045 (4.50% defaults)
}

function runSrtWarRoomSimulator(config: SrtWarRoomConfig, scenarios: StressScenario[]) {
  console.log('=== INDUSTRIAL SYNTHETIC SRT CAPITAL OPTIMIZATION LAB ===');

  const baselineRWA = config.portfolioNotional * config.unsecuritizedRiskWeight;
  const baselineCET1 = baselineRWA * config.targetCET1Ratio;

  // Tranche Notional Breakdown
  const flNotional = config.portfolioNotional * config.firstLossThicknessRate;
  const mezzNotional = config.portfolioNotional * config.mezzanineThicknessRate;
  const protectionNotional = flNotional + mezzNotional;
  const seniorNotional = config.portfolioNotional - protectionNotional;

  // Cumulative Expected Loss
  const cumulativeEL = config.portfolioNotional * (config.annualizedPD * config.weightedAverageLifeYears * config.weightedLGD);

  // Cost of Protection
  const flCost = flNotional * (config.firstLossSpreadBps / 10000);
  const mezzCost = mezzNotional * (config.mezzanineSpreadBps / 10000);
  const totalAnnualCost = flCost + mezzCost;
  const blendedSpreadBps = (totalAnnualCost / protectionNotional) * 10000;

  // Post-SRT RWA and Capital
  const postSrtRWA = seniorNotional * config.seniorRetainedRiskWeight;
  const postSrtCET1 = postSrtRWA * config.targetCET1Ratio;

  const rwaRelief = baselineRWA - postSrtRWA;
  const capitalFreed = baselineCET1 - postSrtCET1;
  const costOfFreedCapital = (totalAnnualCost / capitalFreed) * 100;
  const netValueAdd = (capitalFreed * config.bankCostOfEquity) - totalAnnualCost;

  console.log(`Reference Portfolio: €${(config.portfolioNotional / 1e9).toFixed(2)}B across ${config.borrowerCount} corporate obligors`);
  console.log(`Cumulative Expected Loss: €${(cumulativeEL / 1e6).toFixed(1)}M (${((cumulativeEL / config.portfolioNotional) * 100).toFixed(2)}%)`);
  console.log(`First-Loss Tranche (0.0%-2.5%): €${(flNotional / 1e6).toFixed(1)}M @ +${config.firstLossSpreadBps} bps`);
  console.log(`Mezzanine Tranche (2.5%-7.5%): €${(mezzNotional / 1e6).toFixed(1)}M @ +${config.mezzanineSpreadBps} bps`);
  console.log(`Total Protection Transferred: €${(protectionNotional / 1e6).toFixed(1)}M (7.50% thickness, blended +${blendedSpreadBps.toFixed(1)} bps)`);
  console.log(`Retained Senior Tranche (7.5%-100%): €${(seniorNotional / 1e9).toFixed(2)}B @ 12.0% SEC-IRBA risk weight`);
  console.log(`--------------------------------------------------------`);
  console.log(`Baseline RWA: €${(baselineRWA / 1e9).toFixed(3)}B | Post-SRT RWA: €${(postSrtRWA / 1e9).toFixed(3)}B`);
  console.log(`RWA Relief: €${(rwaRelief / 1e9).toFixed(3)}B (${((rwaRelief / baselineRWA) * 100).toFixed(2)}% reduction)`);
  console.log(`CET1 Capital Freed: €${(capitalFreed / 1e6).toFixed(1)}M`);
  console.log(`Annual Protection Premium: €${(totalAnnualCost / 1e6).toFixed(1)}M`);
  console.log(`Cost of Freed Capital: ${costOfFreedCapital.toFixed(2)}% vs Bank Cost of Equity ${ (config.bankCostOfEquity * 100).toFixed(2) }%`);
  console.log(`Net Annual Shareholder Value Added: +€${(netValueAdd / 1e6).toFixed(1)}M`);
  console.log(`--------------------------------------------------------`);

  console.log('=== MULTI-SCENARIO STRESS LOSS WATERFALL ===');
  scenarios.forEach(sc => {
    const grossLoss = config.portfolioNotional * sc.cumulativeDefaultRate * config.weightedLGD;
    const flLoss = Math.min(flNotional, grossLoss);
    const mezzLoss = Math.min(mezzNotional, Math.max(0, grossLoss - flNotional));
    const seniorLoss = Math.max(0, grossLoss - flNotional - mezzNotional);

    console.log(`Scenario [${sc.name} - Default Rate: ${(sc.cumulativeDefaultRate * 100).toFixed(1)}%]:`);
    console.log(`  Gross Portfolio Credit Losses: €${(grossLoss / 1e6).toFixed(1)}M`);
    console.log(`  First-Loss Absorbed: €${(flLoss / 1e6).toFixed(1)}M (${((flLoss / flNotional) * 100).toFixed(1)}% of tranche)`);
    console.log(`  Mezzanine Absorbed: €${(mezzLoss / 1e6).toFixed(1)}M (${((mezzLoss / mezzNotional) * 100).toFixed(1)}% of tranche)`);
    console.log(`  Bank Senior Retained Impairment: €${(seniorLoss / 1e6).toFixed(1)}M (${((seniorLoss / seniorNotional) * 100).toFixed(2)}%)`);
    console.log(`  Bank Loss Insulation: ${seniorLoss === 0 ? '100% PERFECT IMMUNIZATION' : 'PARTIALLY IMPAIRED'}`);
  });
}

// Run Simulation
runSrtWarRoomSimulator({
  portfolioNotional: 12000000000,
  borrowerCount: 1200,
  annualizedPD: 0.014,
  weightedLGD: 0.40,
  weightedAverageLifeYears: 4.0,
  unsecuritizedRiskWeight: 0.85,
  targetCET1Ratio: 0.12,
  bankCostOfEquity: 0.135,
  firstLossThicknessRate: 0.025,
  firstLossSpreadBps: 1350,
  mezzanineThicknessRate: 0.050,
  mezzanineSpreadBps: 850,
  seniorRetainedRiskWeight: 0.12
}, [
  { name: 'Baseline Mild Cycle', cumulativeDefaultRate: 0.020 },
  { name: 'Severe Recession', cumulativeDefaultRate: 0.045 },
  { name: 'Systemic Financial Crisis', cumulativeDefaultRate: 0.080 }
]);
